"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["6432"],{3685:function(s,n,t){t.r(n),t.d(n,{default:function(){return e}});var a=t(1147);let d=["innerHTML"],e={setup:()=>({html:""}),render:()=>((0,a.wg)(),(0,a.iD)("div",{class:"mi-doc-markdown-body",innerHTML:'<h1>Indicator 指示器</h1>\n<div class="mi-doc-card"><h3 id="jie-shao" tabindex="-1">介绍</h3>\n<p>显示一个任务或流程的进度。</p>\n</div><div class="mi-doc-card"><h3 id="yin-ru" tabindex="-1">引入</h3>\n<p>通过以下方式来全局注册组件，更多注册方式请参考<a href="#/zh-CN/advanced-usage#zu-jian-zhu-ce" target="_blank">组件注册</a>。</p>\n<pre><code class="language-js"><span class="hljs-keyword">import</span> { createApp } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;vue&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Indicator</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@miracle-web/ui&#x27;</span>;\n\n<span class="hljs-keyword">const</span> app = <span class="hljs-title function_">createApp</span>();\napp.<span class="hljs-title function_">use</span>(<span class="hljs-title class_">Indicator</span>);\n</code></pre>\n</div><h2 id="dai-ma-yan-shi" tabindex="-1">代码演示</h2>\n<div class="mi-doc-card"><h3 id="ji-ben-yong-fa" tabindex="-1">基本用法</h3>\n<p>通过 <code>type</code> 属性可以设置指示器的类型，默认为 <code>circle</code>，可选值为 <code>square</code> <code>line</code> <code>capsule</code> <code>numbers</code> <code>pulse</code>。</p>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span> <span class="hljs-attr">:size</span>=<span class="hljs-string">&quot;3&quot;</span> <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;square&quot;</span> <span class="hljs-attr">:size</span>=<span class="hljs-string">&quot;3&quot;</span> <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;capsule&quot;</span> <span class="hljs-attr">:size</span>=<span class="hljs-string">&quot;3&quot;</span> <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;numbers&quot;</span> <span class="hljs-attr">:size</span>=<span class="hljs-string">&quot;3&quot;</span> <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;pulse&quot;</span> <span class="hljs-attr">:size</span>=<span class="hljs-string">&quot;3&quot;</span> <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span> /&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="zi-ding-yi-yan-se" tabindex="-1">自定义颜色</h3>\n<p>通过 <code>color</code> 属性设置激活项颜色；不传时与主题色一致（<code>type=&quot;numbers&quot;</code> 时为激活数字与下划线颜色）。</p>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;#1989fa&quot;</span> /&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="chui-zhi-pai-lie" tabindex="-1">垂直排列</h3>\n<p>设置 <code>direction</code> 属性后，图标和文案会垂直排列。</p>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span> <span class="hljs-attr">:size</span>=<span class="hljs-string">&quot;3&quot;</span> <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span> <span class="hljs-attr">direction</span>=<span class="hljs-string">&quot;vertical&quot;</span> /&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="zi-ding-yi-shu-zi-ge-shi" tabindex="-1">自定义数字格式</h3>\n<p><code>type=&quot;numbers&quot;</code> 时可通过 <code>formatter</code> 自定义每项文案，默认展示为 <code>01</code>、<code>02</code> 这种两位补零格式。</p>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-indicator</span>\n    <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;numbers&quot;</span>\n    <span class="hljs-attr">:size</span>=<span class="hljs-string">&quot;3&quot;</span>\n    <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span>\n    <span class="hljs-attr">:formatter</span>=<span class="hljs-string">&quot;(index) =&gt; `Step ${index + 1}`&quot;</span>\n/&gt;</span>\n</code></pre>\n</div><h2 id="api" tabindex="-1">API</h2>\n<div class="mi-doc-card"><h3 id="props" tabindex="-1">Props</h3>\n<table>\n<thead>\n<tr>\n<th>参数</th>\n<th>说明</th>\n<th>类型</th>\n<th>默认值</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>color</td>\n<td>颜色</td>\n<td><em>string</em></td>\n<td><code>#006fee</code></td>\n</tr>\n<tr>\n<td>type</td>\n<td>类型，可选值为 <code>square</code> <code>line</code> <code>capsule</code> <code>numbers</code> <code>pulse</code></td>\n<td><em>string</em></td>\n<td><code>circle</code></td>\n</tr>\n<tr>\n<td>size</td>\n<td>集合总长度</td>\n<td><em>number</em></td>\n<td><code>1</code></td>\n</tr>\n<tr>\n<td>active</td>\n<td>激活的项</td>\n<td><em>number</em></td>\n<td><code>0</code></td>\n</tr>\n<tr>\n<td>direction</td>\n<td>排列方向，可选值为 <code>vertical</code></td>\n<td><em>string</em></td>\n<td><code>horizontal</code></td>\n</tr>\n<tr>\n<td>formatter</td>\n<td><code>numbers</code> 类型下的文案格式化函数</td>\n<td><em>(index: number) =&gt; string</em></td>\n<td>-</td>\n</tr>\n</tbody>\n</table>\n</div><div class="mi-doc-card"><h3 id="lei-xing-ding-yi" tabindex="-1">类型定义</h3>\n<p>组件导出以下类型定义：</p>\n<pre><code class="language-ts"><span class="hljs-keyword">import</span> <span class="hljs-keyword">type</span> { <span class="hljs-title class_">IndicatorProps</span>, <span class="hljs-title class_">IndicatorDirection</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@miracle-web/ui&#x27;</span>;\n</code></pre>\n</div><h2 id="zhu-ti-ding-zhi" tabindex="-1">主题定制</h2>\n<div class="mi-doc-card"><h3 id="yang-shi-bian-liang" tabindex="-1">样式变量</h3>\n<p>组件提供了下列 CSS 变量，可用于自定义样式，使用方法请参考 <a href="#/zh-CN/config-provider" target="_blank">ConfigProvider 组件</a>。</p>\n<table>\n<thead>\n<tr>\n<th>名称</th>\n<th>默认值</th>\n<th>描述</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>--mi-indicator-active-background</td>\n<td><em>var(--mi-primary-color)</em></td>\n<td>各 <code>type</code> 激活态颜色（<code>numbers</code> 为文字/下划线）</td>\n</tr>\n<tr>\n<td>--mi-indicator-inactive-background</td>\n<td><em>var(--mi-border-color)</em></td>\n<td>各 <code>type</code> 未激活态颜色</td>\n</tr>\n<tr>\n<td>--mi-indicator-circle-size</td>\n<td><em>6px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-square-size</td>\n<td><em>8px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-line-width</td>\n<td><em>30px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-line-height</td>\n<td><em>4px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-line-radius</td>\n<td><em>4px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-capsule-size</td>\n<td><em>8px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-capsule-active-width</td>\n<td><em>28px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-numbers-font-size</td>\n<td><em>13px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-pulse-size</td>\n<td><em>10px</em></td>\n<td>-</td>\n</tr>\n<tr>\n<td>--mi-indicator-pulse-ring-width</td>\n<td><em>2px</em></td>\n<td>-</td>\n</tr>\n</tbody>\n</table>\n</div>'},null,8,d))}}}]);